use verus::prelude::*;

#[verifier(nonlinear)]
#[requires(
    // The input slice must be sorted in non‐decreasing order
    forall|i: usize, j: usize| i < j && j < a.len() ==> a[i] <= a[j]
)]
#[ensures(
    // We return true exactly when k occurs somewhere in a[0..a.len())
    result <==> (exists|i: usize| i < a.len() && a[i] == k)
)]
fn bin_search(a: &[i32], k: i32) -> bool {
    let mut lo: usize = 0;
    let mut hi: usize = a.len();
    #[invariant(
        // 0 ≤ lo ≤ hi ≤ a.len()
        lo <= hi,
        hi <= a.len()
    )]
    #[invariant(
        // All indices below lo have a[i] < k
        forall|i: usize| i < lo ==> a[i] < k
    )]
    #[invariant(
        // All indices at or above hi have a[i] > k
        forall|i: usize| hi <= i && i < a.len() ==> a[i] > k
    )]
    #[decreases(hi - lo)]
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] == k {
            return true;
        } else if a[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    false
}